interface Observer {
    fun onUpdate(event: String)
}

class EventBus {
    private val observers = mutableListOf<Observer>()

    fun subscribe(observer: Observer) { observers.add(observer) }
    fun unsubscribe(observer: Observer) { observers.remove(observer) }
    fun publish(event: String) { observers.forEach { it.onUpdate(event) } }
}

class Logger : Observer {
    override fun onUpdate(event: String) = println("Log: $event")
}

class Analytics : Observer {
    override fun onUpdate(event: String) = println("Track: $event")
}

// Usage
