class NetworkRequest private constructor(
    val url: String,
    val method: String,
    val headers: Map<String, String>,
    val timeout: Int,
    val retries: Int
) {
    class Builder(private val url: String) {
        private var method = "GET"
        private var headers = mutableMapOf<String, String>()
        private var timeout = 30
        private var retries = 3

        fun method(method: String) = apply { this.method = method }
        fun header(key: String, value: String) = apply { headers[key] = value }
        fun timeout(seconds: Int) = apply { timeout = seconds }
        fun retries(count: Int) = apply { retries = count }
        fun build() = NetworkRequest(url, method, headers, timeout, retries)
    }
}

// Usage
