class UserRepositoryImpl(
    private val api: UserApiService,
    private val dao: UserDao
) : UserRepository {
    override suspend fun getUser(id: Int): User {
        val cached = dao.getUser(id)
        if (cached != null) return cached      // Return from DB cache
        val remote = api.getUser(id)           // Fetch from network
        dao.insertUser(remote)                 // Cache it
        return remote
    }
}

