// Facade — simple interface for complex workflow
class VideoProcessor(
    private val decoder: VideoDecoder = VideoDecoder(),
    private val mixer: AudioMixer = AudioMixer(),
    private val encoder: VideoEncoder = VideoEncoder(),
    private val storage: FileStorage = FileStorage()
) {
    fun process(inputFile: String, outputPath: String) {
        decoder.decode(inputFile)
        mixer.mix(inputFile)
        encoder.encode(outputPath)
        storage.save(outputPath)
    }
}

