interface ImageCacheStrategy {
    fun cache(url: String, bitmap: Bitmap)
    fun retrieve(url: String): Bitmap?
}

class MemoryCacheStrategy : ImageCacheStrategy {
    private val cache = HashMap<String, Bitmap>()
    override fun cache(url: String, bitmap: Bitmap) { cache[url] = bitmap }
    override fun retrieve(url: String) = cache[url]
}

class DiskCacheStrategy : ImageCacheStrategy {
    override fun cache(url: String, bitmap: Bitmap) { /* write to disk */ }
    override fun retrieve(url: String): Bitmap? = null /* read from disk */
}

class ImageLoader(private var strategy: ImageCacheStrategy) {
    fun setStrategy(s: ImageCacheStrategy) { strategy = s }
    fun load(url: String): Bitmap? {
        return strategy.retrieve(url) ?: fetchFromNetwork(url).also {
            if (it != null) strategy.cache(url, it)
        }
    }
    private fun fetchFromNetwork(url: String): Bitmap? = null
}

