interface Command {
    fun execute()
    fun undo()
}

class TextEditor {
    val text = StringBuilder()
}

class InsertCommand(private val editor: TextEditor, private val text: String) : Command {
    override fun execute() { editor.text.append(text) }
    override fun undo() { editor.text.delete(editor.text.length - text.length, editor.text.length) }
}

class CommandHistory {
    private val history = ArrayDeque<Command>()
    fun execute(command: Command) { command.execute(); history.addLast(command) }
    fun undo() { history.removeLastOrNull()?.undo() }
}

// Usage
val editor = TextEditor()
val history = CommandHistory()
history.execute(InsertCommand(editor, "Hello "))
history.execute(InsertCommand(editor, "World"))
println(editor.text) // Hello World
history.undo()
println(editor.text) // Hello

abstract class DataExporter {
    // Template method — defines the algorithm skeleton
    fun export(data: List<Any>) {
        val formatted = format(data)       // Step 1: abstract
        validate(formatted)                // Step 2: concrete default
        write(formatted)                   // Step 3: abstract
        notifyComplete()                   // Step 4: concrete hook
    }

    abstract fun format(data: List<Any>): String
    abstract fun write(content: String)

    open fun validate(content: String) {
        if (content.isEmpty()) throw IllegalStateException("Empty content")
    }

    open fun notifyComplete() = println("Export complete")
}

class CsvExporter : DataExporter() {
    override fun format(data: List<Any>) = data.joinToString(",")
    override fun write(content: String) = println("Writing CSV: $content")
}

class JsonExporter : DataExporter() {
    override fun format(data: List<Any>) = "{\"data\": $data}"
    override fun write(content: String) = println("Writing JSON: $content")
}

