abstract class AuthHandler(private var next: AuthHandler? = null) {
    fun setNext(handler: AuthHandler): AuthHandler {
        next = handler
        return handler
    }
    fun handle(request: AuthRequest) {
        if (canHandle(request)) process(request)
        else next?.handle(request) ?: println("No handler found")
    }
    abstract fun canHandle(request: AuthRequest): Boolean
    abstract fun process(request: AuthRequest)
}

data class AuthRequest(val type: String, val token: String)

class ApiKeyHandler : AuthHandler() {
    override fun canHandle(r: AuthRequest) = r.type == "API_KEY"
    override fun process(r: AuthRequest) = println("Validated API key: ${r.token}")
}

class JwtHandler : AuthHandler() {
    override fun canHandle(r: AuthRequest) = r.type == "JWT"
    override fun process(r: AuthRequest) = println("Validated JWT: ${r.token}")
}

// Build chain
