interface FileSystemItem {
    val name: String
    fun size(): Long
    fun print(indent: String = "")
}

class File(override val name: String, private val bytes: Long) : FileSystemItem {
    override fun size() = bytes
    override fun print(indent: String) = println("$indent📄 $name ($bytes bytes)")
}

class Folder(override val name: String) : FileSystemItem {
    private val children = mutableListOf<FileSystemItem>()
    fun add(item: FileSystemItem) { children.add(item) }
    override fun size() = children.sumOf { it.size() }
    override fun print(indent: String) {
        println("$indent📁 $name")
        children.forEach { it.print("$indent  ") }
    }
}

