// State — immutable UI snapshot
data class UserState(
    val isLoading: Boolean = false,
    val user: User? = null,
    val error: String? = null
)

class UserViewModel(private val repo: UserRepository) : ViewModel() {
    private val _state = MutableStateFlow(UserState())
    val state: StateFlow<UserState> = _state

    fun handleIntent(intent: UserIntent) = viewModelScope.launch {
        when (intent) {
            is UserIntent.LoadUser -> {
                _state.value = UserState(isLoading = true)
                try {
                    val user = repo.getUser(intent.id)
                    _state.value = UserState(user = user)
                } catch (e: Exception) {
                    _state.value = UserState(error = e.message)
                }
            }
            UserIntent.Retry -> handleIntent(UserIntent.LoadUser(1))
            UserIntent.Logout -> _state.value = UserState()
        }
    }
}

// Intrinsic (shared) state — same for many objects
data class IconStyle(val color: String, val size: Int, val shape: String)

// Flyweight factory — reuses existing instances
object IconFactory {
    private val cache = HashMap<String, IconStyle>()

    fun getIcon(color: String, size: Int, shape: String): IconStyle {
        val key = "$color-$size-$shape"
        return cache.getOrPut(key) { IconStyle(color, size, shape) }
    }
}

// Extrinsic (unique) state stored externally
